#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long jumps = 0, curEnd = 0, farthest = 0;
    for (long long i = 0; i < n - 1; i++) {
        farthest = max(farthest, i + a[i]);
        if (i == curEnd) {
            jumps++;
            curEnd = farthest;
        }
    }
    cout << jumps << "\n";

    return 0;
}

